findAction=function(){if(!alive||insideBin)return basicFindAction();if(inFront(shop,2.7))return {type:'shop'};let f=foods.find(f=>!f.eaten&&(!f.fridge||fridge.open)&&!!f.sewer===underground&&inFront(f,1.8));if(f)return {type:'eat',object:f};if(inFront(fridge,2.6))return {type:'fridge',object:fridge};let d=doors.find(d=>Math.hypot(player.x-d.x,player.z-d.z)<2.5);if(d)return {type:'door',object:d};return basicFindAction()};
