document.getElementById('pauseButton').onclick=()=>togglePause();document.getElementById('resumeButton').onclick=()=>togglePause(false);
document.getElementById('soundButton').onclick=()=>{settings.sound=!settings.sound;initAudio();if(windGain)windGain.gain.value=settings.sound&&!paused?.03:0;saveSettings();updateSettingsUI()};
document.getElementById('sensitivity').oninput=e=>{settings.sensitivity=Math.max(.4,Math.min(2,Number(e.target.value)));saveSettings()};
for(let k of['low','auto','high'])document.getElementById('quality-'+k).onclick=()=>{settings.quality=k;globalThis.ratPixelCap=k==='low'?1:k==='high'?2:1.5;saveSettings();resize();updateSettingsUI()};
function updateSettingsUI(){document.getElementById('soundButton').textContent=settings.sound?'Sound on':'Sound off';document.getElementById('sensitivity').value=settings.sensitivity;for(let k of['low','auto','high'])document.getElementById('quality-'+k).className=settings.quality===k?'selected':''}updateSettingsUI();
