function applySave(){if(!S.legacy)S.legacy={upgrades:{},ownedWeapons:[],weapon:'none',ownedHats:[],hat:'none'};if(!S.world)S.world={};if(!S.position){underground=false;player.x=player.z=player.angle=yaw=0;jumpY=jumpV=0;pitch=.38;cameraYaw=cameraPitch=null}coins=clamp(finite(S.coins,coins),0,999999);if(S.legacy){for(const k of Object.keys(upgrades))upgrades[k]=clamp(finite(S.legacy.upgrades?.[k]),0,5);ownedWeapons=['none',...(S.legacy.ownedWeapons||[]).filter(x=>weapons[x])];weapon=ownedWeapons.includes(S.legacy.weapon)?S.legacy.weapon:'none';ownedHats=['none',...(S.legacy.ownedHats||[]).filter(x=>hats[x])];hat=ownedHats.includes(S.legacy.hat)?S.legacy.hat:'none'}hunger=S.hunger||100;health=Math.min(maxHealth(),S.health||maxHealth());if(S.world){for(const [a,k,p]of[[foods,'food','eaten'],[coinDrops,'coins','taken'],[traps,'traps','sprung'],[bins,'bins','searched'],[doors,'doors','open'],[drains,'drains','open']])a.forEach((o,i)=>{o[p]=!!S.world[k]?.[i]})}const pos=S.position;if(pos&&Number.isFinite(pos.x)&&Number.isFinite(pos.z)){underground=!!pos.underground;player.x=clamp(pos.x,-67,67);player.z=clamp(pos.z,-67,67);if(underground&&!sewerPassable(player.x,player.z)){player.x=0;player.z=8}player.angle=finite(pos.angle);yaw=finite(pos.yaw);pitch=clamp(finite(pos.pitch,.38),.05,.8)}plusMode=S.pack;if(S.pack){for(const k of ['robot','ninja','gold','wings'])if(!S.cosmetics.includes(k))S.cosmetics.push(k);for(const k of ['arcade','goldBed','neon'])if(!S.decorOwned.includes(k))S.decorOwned.push(k)}document.body.classList.toggle('ratlife-plus',S.pack);settings={...settings,sensitivity:S.settings.sensitivity,quality:S.settings.quality,sound:S.settings.master>0};globalThis.ratPixelCap=settings.quality==='low'?1:settings.quality==='high'?2:1.5;document.body.classList.toggle('reducedMotion',!!S.settings.reduced);document.body.classList.toggle('bigTouch',!!S.settings.bigTouch);refreshHUD()}
