function startMission(id){const m=missions.find(x=>x.id===id);if(!m||!available(m)||missionState(m).status!=='available')return false;S.missions[id]={step:0,status:'active',flags:[]};S.tracked=id;message(m.npc,missionDialogue(m));announce('Mission started: '+m.name);save();return true}
function missionDialogue(m){return ({first:'Pip: “A crumb by the path! Grab it, then come say hello.”',delivery:'Pip: “Mabel’s expecting this tiny parcel. Keep it dry!”',pipes:'Rivet: “Brass key, western pipe. My paws are too big for that bend.”',race:'Dash: “Quick feet beat fancy wings. Follow the pennants!”',nest:'Fern: “Two bits of wood, two soft scraps. Home begins small.”',stash:'Mabel: “Someone left scratched arrows by the alley. Follow your whiskers.”',helper:'Fern: “A snack, a little sorting, a pipe check. That’s neighbourly.”',picnic:'Mabel: “Bread, berries and a plate. Then invite our friends!”',sky:'Dash: “Our old rooftop radio has gone quiet. Look above Crate Alley.”'})[m.id]}
function completeStage(m){const st=missionState(m);if(st.status!=='active')return;if(m.id==='delivery'&&st.step===0)S.bag.parcel=1;st.step++;if(st.step>=m.stages.length){st.status='done';if(m.id==='delivery')delete S.bag.parcel;coins+=m.reward;S.bag.snack=(S.bag.snack||0)+1;if(m.id==='first'){S.phone=true;S.cosmetics.push('cap');message('Pip','Your rat phone is ready. Map, missions and notes are all free. Press M or tap the phone.')}if(m.id==='pipes'&&!S.cosmetics.includes('helmet'))S.cosmetics.push('helmet');if(m.id==='nest'&&!S.cosmetics.includes('backpack'))S.cosmetics.push('backpack');if(m.id==='picnic'){S.decorOwned.push('plant');message('Mabel','The picnic is on! Thanks for bringing the whole neighbourhood together.')}announce(m.name+' complete · +'+m.reward+' coins');sound(650,.22,'triangle',.06,1150);S.tracked=missions.find(x=>available(x)&&missionState(x).status!=='done'&&!x.pack)?.id||''}else{announce(m.name+': '+m.stages[st.step][0])}refreshHUD();save()}
function event(kind){for(const m of missions){const st=missionState(m);if(st.status==='active'&&m.stages[st.step]?.[1]===kind)completeStage(m)}}
function checkMissions(){for(const m of missions){const st=missionState(m);if(st.status!=='active')continue;const kind=m.stages[st.step]?.[1];if(S.collected.includes(kind))completeStage(m);else if(kind==='materials'&&(S.bag.wood||0)>=2&&(S.bag.cloth||0)>=2)completeStage(m);else if(kind==='decorate'&&S.decor.length>=2)completeStage(m);else if(kind==='picnicItems'&&['picnicBread','picnicBerry','picnicPlate'].every(x=>S.collected.includes(x)))completeStage(m);else if(kind==='invites'&&st.flags?.includes('pip')&&st.flags?.includes('fern'))completeStage(m);else if(kind?.startsWith('visit:')){const loc=landmarks.find(x=>x.id===kind.slice(6));if(loc&&!!loc.sewer===underground&&Math.hypot(player.x-loc.x,player.z-loc.z)<3&&jumpY<.5)completeStage(m)}}}
function collect(o){if(S.collected.includes(o.id))return false;if(o.pack&&!S.pack)return false;if(o.kind==='stash'&&!S.collected.includes('clue2')){say('A locked supply tin. Find the blue ribbon first.');return false}S.collected.push(o.id);if(o.kind==='cheese'){coins+=4;hunger=Math.min(100,hunger+12)}else if(o.kind==='cap'){coins+=3;S.bag.caps=(S.bag.caps||0)+1}else if(o.kind==='cloth'||o.kind==='wood')S.bag[o.kind]=(S.bag[o.kind]||0)+1;else if(o.kind==='crumb')hunger=Math.min(100,hunger+25);else if(o.kind==='stash')coins+=8;event(o.id);if(o.kind==='clue')message('Mabel',o.id==='clue1'?'The scratch points northwest. Look for a blue ribbon beyond Crate Alley.':'The ribbon points further northwest, towards the old supply tin.');say('Found '+o.name);sound(680,.12,'sine',.05,1100);checkMissions();save();return true}
