function stopInput(){clear();runHeld=false;velocityX=velocityZ=0;landJet();document.exitPointerLock?.()}
function showModal(title,html,back=null){modalOpen=true;modalBack=back;stopInput();$('rlModalTitle').textContent=title;$('rlModalBody').innerHTML=html;$('rlModal').hidden=false}
