function newGame(){if(!globalThis.RatlifeNickname){globalThis.dispatchEvent(new Event('ratlife:need-name'));return}const action=()=>{const pack=S.pack,opts=S.settings;S=initial();S.pack=pack;S.settings=opts;S.coins=8;validSave=false;originalRestart();landJet();returnDrone();activity=null;applySave();begin();};if(S.started||validSave)confirmAction('Start a new game?','This replaces your current adventure in this browser. Your Rat Pack unlock and settings will be kept.',action);else action()}
function refreshMenu(){$('playContinue').textContent=S.started?'Continue':'Play Ratlife';$('packTitle').textContent=S.pack?'Rat Pack Active':'THE RAT PACK';$('packButton').textContent='See Rat Pack features';$('packState').textContent=S.pack?'Server-verified extras active.':'Optional Ratlife Plus membership';$('menuSave').textContent=storageError?'Browser storage is unavailable.':'Local saves belong to this browser.'}
function packDetails(){showModal(S.pack?'The Rat Pack · Active':'The Rat Pack',`<p>The Rat Pack is the optional Ratlife Plus membership. Ask Bob for an access code.</p><div class="rl-card"><h4>Fly</h4><p>Rechargeable jetpack, fuel controls and optional aerial ring challenges.</p></div><div class="rl-card"><h4>Connect</h4><p>Phone music, a scouting drone and saved wallpaper themes.</p></div><div class="rl-card"><h4>Create</h4><p>Robot, ninja and golden styles, extra nest furniture and photo filters.</p></div><div class="rl-card"><h4>Explore</h4><p>A rooftop hideout and the optional Rooftop Radio side mission.</p></div><p><b>The main adventure, normal progression and core gameplay are free.</b></p>${S.pack?'<p class="rl-tag">Rat Pack Active</p>':'<button class="rl-btn gold" id="enterPackCode">Enter access code</button>'}<p class="rl-muted">Membership is checked with the server. Accounts are optional. Ordinary offline play stays available; premium extras need an online check.</p>`);if(!S.pack)$('enterPackCode').onclick=()=>{closeModal();openCode()}}
function openCode(){plusCode.hidden=false;$('packCode').value='';$('codeMessage').textContent='';stopInput();setTimeout(()=>$('packCode').focus(),40)}
// Replace this local prototype adapter with a server membership verifier in a hosted release.
async function validateMembership(code){if(!globalThis.RatlifeAccount)throw Error('Online membership check is unavailable. Try again when connected.');return globalThis.RatlifeAccount.redeemPack(code)}
async function unlock(e){e.preventDefault();let ok;try{ok=await validateMembership($('packCode').value)}catch(e){$('codeMessage').textContent=e.message;return}if(!ok){$('codeMessage').textContent='That code didn’t work. Check it and try again, or ask Bob for help.';return}S.pack=true;plusMode=true;document.body.classList.add('ratlife-plus');for(const key of ['robot','ninja','gold','wings'])if(!S.cosmetics.includes(key))S.cosmetics.push(key);for(const key of ['arcade','goldBed','neon'])if(!S.decorOwned.includes(key))S.decorOwned.push(key);plusCode.hidden=true;S.started=S.started||validSave;write(KEY,{...snapshot(),pack:true});refreshMenu();showModal('Welcome to The Rat Pack!','<div class="unlockAnim"><p>★ Your extras are ready.</p><ul><li>Rechargeable jetpack and aerial rings</li><li>Music, scouting drone and phone themes</li><li>Robot, ninja and golden rat styles</li><li>Extra nest furniture and photo filters</li><li>Rooftop Radio bonus story</li></ul><button class="rl-btn gold" id="unlockDone">Back to Ratlife</button></div>');$('unlockDone').onclick=closeModal}
function controlsHTML(){return '<div class="rl-card"><b>Keyboard & mouse</b><p>WASD or arrows · move<br>Shift · run<br>Space · jump / jetpack ascend<br>E or left click · interact<br>F or right click · attack<br>M · phone / close phone<br>J · jetpack on/off (Rat Pack)<br>Ctrl · descend while flying<br>R · reset camera<br>Escape · back / pause</p></div><div class="rl-card"><b>Touch</b><p>Left joystick · move<br>Drag the world · look<br>Run · toggle running<br>Jump / context action · jump or interact<br>Phone · open apps<br>Rocket · toggle flight; Jump ascends, Down descends</p></div><p>Click the world to lock the mouse. Browsers require a gesture for pointer lock. The phone pauses play. Hunger is forgiving; Relaxed Hunger stops depletion.</p><p>Open Help for an unstuck action. Progress autosaves locally; collecting secrets and mission rewards is permanent.</p>'}
function whatsNew(){showModal('What’s New · Backyard Stories','<p>Big free update: new missions, more secrets, better movement, a basic rat phone and a livelier world.</p><ul><li>Eight connected free missions, from First Crumb to The Big Picnic</li><li>Hidden cheese, bottle caps, landmarks and a collectible album</li><li>Four repeatable courses and a memory challenge</li><li>A starter nest, placement planner, cosmetics and a new shop catalogue</li><li>Versioned autosaves, safer menus, solid sewer ceilings and steadier camera movement</li><li>The Rat Pack: optional flight, music, drone, themes and rooftop story</li></ul>')}
function appHead(title){return `<div class="phoneAppHead"><h3>${esc(title)}</h3><button data-ui="home">‹ Apps</button></div>`}
function home(){currentApp='';$('phoneApps').hidden=false;$('phoneContent').hidden=true;$('phoneBack').textContent='⌂';renderPhoneStatus()}
function openApp(id){if(id==='messages'){S.readMessages=S.messages.map(x=>x.id);save(true);renderPhoneStatus()}currentApp=id;$('phoneApps').hidden=true;$('phoneContent').hidden=false;$('phoneBack').textContent='‹ Back';renderApp()}
function openRatPhone(app=''){if(menuOpen||shopOpen||!alive)return;if(!S.phone){say('Meet Pip after collecting the first crumb to receive your phone.');return}phoneOpen=true;paused=false;$('pausePanel').hidden=true;stopInput();ratPhone.hidden=false;ratPhone.style.display='';if(app)openApp(app);else home();renderPhoneStatus()}
function closeRatPhone(){phoneOpen=false;ratPhone.hidden=true;currentApp='';restoreControls()}
function renderPhoneStatus(){const hours=Math.floor(S.gameTime/60)%24,mins=Math.floor(S.gameTime)%60;$('phoneClock').textContent=String(hours).padStart(2,'0')+':'+String(mins).padStart(2,'0');const n=S.messages.filter(x=>!S.readMessages.includes(x.id)).length;$('notificationButton').textContent='☷ '+(n||'');$('phoneNetwork').textContent=S.pack?'RAT PACK · 5G':'RAT · 4G'}
function renderApp(){const el=$('phoneContent');const titles={map:'Backyard Map',missions:'Mission Journal',inventory:'Your Inventory',messages:'Rat Messages',camera:'Rat Camera',notes:'Rat Notes',calculator:'Calculator',settings:'Settings',nest:'Nest Planner',achievements:'Achievements',album:'Collectible Album',help:'Help',music:'Rat Tunes',drone:'Scout Drone',themes:'Phone Themes',styles:'Wardrobe',activities:'Activities',shop:'The Rat Market'};el.innerHTML=appHead(titles[currentApp]||'Rat Phone')+appBody(currentApp);bindApp();}
function appBody(app){switch(app){
case 'map':return renderMap();
case 'missions':return renderMissions();
case 'inventory':return `<p class="rl-muted">Coins: ${coins}. Quest items cannot be discarded.</p><div class="inventoryGrid">${Object.entries(S.bag).map(([k,n])=>`<div class="rl-card"><b>${({snack:'🍞 Snacks',wood:'▥ Driftwood',cloth:'▦ Soft cloth',caps:'◉ Bottle caps'})[k]||esc(k)}</b><p>× ${n}</p><small>${k==='snack'?'Restore 35 hunger.':k==='caps'?'Collected keepsakes.':'Nest materials and quest supplies.'}</small>${k==='snack'?'<button data-ui="eatSnack" '+(!n?'disabled':'')+'>Eat snack</button>':''}</div>`).join('')}</div><h4>Quest pouch</h4>${S.collected.filter(x=>['lostKey','stash','picnicBread','picnicBerry','picnicPlate'].includes(x)).map(x=>'<p>◆ '+esc(lootItems.find(o=>o.id===x)?.name)+'</p>').join('')||'<p class="rl-muted">No quest objects yet.</p>'}<h4>Storage crate</h4><p class="rl-muted">Store snacks at your nest. Quest items stay with you.</p><p>Stored snacks: ${S.bag.stored||0}</p><button data-ui="storeSnack">Store one</button> <button data-ui="takeSnack">Take one</button><p><button data-ui="styles">Open wardrobe</button></p>`;
case 'messages':return `<p class="rl-muted">Fictional conversations with your neighbours.</p>${S.messages.slice().reverse().map(x=>`<div class="rl-card"><b>🐀 ${esc(npcs.find(n=>n.id===x.from)?.name||x.from)}</b><p>${esc(x.text)}</p></div>`).join('')||'<p>No messages yet. Talk to Pip to begin.</p>'}`;
case 'camera':return `<p>Photograph the game world — no real camera access.</p>${photoData?'<img id="latestPhoto" style="width:100%;border-radius:13px" alt="Latest Ratlife capture" src="'+photoData+'">':'<div class="rl-card">Your next backyard memory starts here.</div>'}<button class="rl-btn" data-ui="photoMode">Hide HUD & frame photo</button><p><button data-ui="capture">Capture now</button> <button data-ui="downloadPhoto" ${photoData?'':'disabled'}>Download latest</button></p>${S.pack?`<label>Rat Pack filter <select class="rl-input" id="photoFilter">${['none','warm','noir','forest','postcard'].map(x=>`<option ${S.photoFilter===x?'selected':''}>${x}</option>`).join('')}</select></label><p class="rl-muted">Warm, noir and forest colour grades; postcard includes a frame.</p>`:''}<p id="captureStatus" class="rl-muted">Captures stay in memory until this page closes. Downloads depend on browser support.</p>`;
case 'notes':return `<textarea class="rl-input" id="noteDraft" placeholder="A secret cheese location…" maxlength="4000" style="height:120px"></textarea><button class="rl-btn" data-ui="addNote">Save new note</button>${S.notes.map((n,i)=>`<div class="rl-card noteItem"><textarea class="rl-input" data-note="${i}" maxlength="4000">${esc(n.text)}</textarea><p><button data-save-note="${i}">Save changes</button> <button data-delete-note="${i}">Delete</button></p></div>`).join('')}<details><summary>Optional field notes</summary><p>Rivet lives below the Market Drain. Blue ribbons lead northwest. Dash’s flags mark a short route. Materials for Fern lie west of the market.</p></details>`;
case 'calculator':return `<div class="calcDisplay" id="calcDisplay">${esc(calc)}</div><div class="calcKeys">${['C','⌫','÷','×','7','8','9','−','4','5','6','+','1','2','3','=','0','.','(',')'].map(x=>`<button data-calc="${x}">${x}</button>`).join('')}</div>`;
case 'settings':return settingsHTML();
case 'help':return controlsHTML()+'<button class="rl-btn" data-ui="unstuck">Unstuck · return to nest</button><p class="rl-muted">Keeps your progress and inventory.</p><details><summary>The Rat Pack</summary><p>Optional Ratlife Plus membership: jetpack, phone extras, styles and bonus missions. Ask Bob for a Rat Pack access code. The main game is free.</p></details>';
case 'album':return `<p>${S.collected.filter(x=>x.startsWith('cheese')).length}/12 cheese · ${S.collected.filter(x=>x.startsWith('cap')).length}/10 caps</p><div class="albumGrid">${lootItems.filter(x=>['cheese','cap'].includes(x.kind)).map(x=>`<div class="albumTile ${S.collected.includes(x.id)?'':'missing'}">${S.collected.includes(x.id)?x.kind==='cheese'?'🧀':'◉':'?'}<br>${esc(x.name)}</div>`).join('')}</div><h4>Landmarks</h4>${landmarks.filter(x=>S.discovered.includes(x.id)).map(x=>'<p>✓ '+esc(x.name)+'</p>').join('')}`;
case 'achievements':return [['sewers','Under the Backyard','Enter the sewers',underground?1:0,1],['caps','Cap Collector','Collect five bottle caps',S.bag.caps||0,5],['decor','Home Maker','Place three nest decorations',S.decor.length,3],['racer','Fast Paws','Finish any timed activity',Object.keys(S.records).length,1],['picnic','Picnic Hero','Complete The Big Picnic',S.missions.picnic?.status==='done'?1:0,1]].map(([id,title,desc,n,max])=>`<div class="rl-card"><b>${S.achievements.includes(id)?'★':'☆'} ${title}</b><p>${desc}</p><small>${Math.min(n,max)} / ${max} · ${S.achievements.includes(id)?'Reward earned':'One-time coin reward'}</small></div>`).join('');
case 'nest':return nestHTML();
case 'styles':return stylesHTML();
case 'activities':return `<p class="rl-muted">Repeatable routes reward skill. No paid extras needed for the free routes.</p>${Object.entries(routes).filter(([k,x])=>!x.pack||S.pack).map(([k,x])=>`<div class="rl-card"><b>${x.name}</b><p>${x.limit}s · ${x.reward} coins on finish${x.pack?' · Rat Pack':''}</p><small>Best: ${S.records[k]?S.records[k].toFixed(1)+'s':'Not finished'}</small><p><button data-route="${k}">Set start waypoint</button>${nearRoute(k)?` <button data-start-route="${k}">Start route</button>`:''}</p></div>`).join('')}<div class="rl-card"><b>Mabel’s Memory</b><p>Repeat a four-note sequence. 6 coins for a correct round.</p><button data-ui="memoryWaypoint">Find Mabel</button>${near(npcs[1],4)?' <button data-ui="memory">Play</button>':''}</div>`;
case 'shop':return shopHTML();
case 'music':return musicHTML();
case 'themes':return `<p>Choose a wallpaper and matching accent.</p>${[['moss','Moss','#6d8f67'],['midnight','Midnight','#344b72'],['sunset','Sunset','#ba7964'],['cheese','Cheese','#a88e42']].map(([id,n,c])=>`<button data-theme="${id}" style="width:100%;margin:6px 0;background:${c};color:white;min-height:54px">${n}${S.theme===id?' ✓':''}</button>`).join('')}`;
case 'drone':return `<p>A rat-built scout with a 25m tether and 25-second flight time. Launch outdoors on safe ground.</p><div class="rl-card"><b>Controls</b><p>WASD / left joystick · fly<br>Space / Jump · rise<br>Ctrl / Down · descend<br>Mouse / drag · look<br>J or Escape · safe return</p></div><button class="rl-btn" data-ui="launchDrone">Launch scout</button><p class="rl-muted">Scouting cannot collect objects or complete missions. The rat waits safely at launch.</p>`;
default:return '<p>This app is unavailable.</p>'}}
function renderMap(){const p=(x)=>(x+68)/136*100;return `<div class="phoneMap"><svg viewBox="0 0 136 136" aria-label="Map of the Ratlife backyard"><rect width="136" height="136" fill="#667f53"/><path d="M0 80H136M68 0V136" stroke="#b0a080" stroke-width="6"/><rect x="57" y="40" width="22" height="15" rx="2" fill="#c3bda4"/><rect x="34" y="84" width="12" height="10" fill="#7b6750"/><path d="M38 76H98M68 38V103" stroke="#284b4a" stroke-width="3" stroke-dasharray="3 2"/><text x="55" y="37" font-size="5" fill="#fff">HOUSE</text><text x="90" y="110" font-size="5" fill="#fff">PICNIC</text></svg>${landmarks.filter(x=>S.discovered.includes(x.id)).map(x=>`<button data-dest="${x.id}" title="${esc(x.name)}" style="left:${p(x.x)}%;top:${p(x.z)}%">${x.icon||'🐀'}</button>`).join('')}<span class="mapPlayerNeedle" style="left:${p(player.x)}%;top:${p(player.z)}%;transform:translate(-50%,-50%) rotate(${180-player.angle*180/Math.PI}deg)">▲</span></div><p>${underground?'Sewers':'Surface'} · ${Math.round(player.x)}, ${Math.round(player.z)}</p><p class="rl-muted">Select a discovered landmark for a waypoint. Dashed lines show the known main pipes. Discover more places by exploring.</p>${S.waypoint?`<div class="rl-card">Destination: ${esc(S.waypoint.name)}<br><button data-ui="clearWaypoint">Clear waypoint</button></div>`:''}`}
function renderMissions(){return `<div class="phoneTabs">${['active','available','done'].map(x=>`<button data-mission-tab="${x}" class="${S.missionTab===x?'selected':''}">${x==='done'?'Completed':x[0].toUpperCase()+x.slice(1)}</button>`).join('')}</div>${missions.filter(m=>available(m)&&missionState(m).status===S.missionTab).map(m=>{const st=missionState(m);return `<div class="rl-card"><h4>${esc(m.name)} ${m.pack?'★':''}</h4><p>${esc(m.summary)}</p><small>${m.reward} coins + snack · ${npcs.find(n=>n.id===m.npc)?.name}</small>${st.status==='active'?`<p>${st.step+1}/${m.stages.length}: ${esc(m.stages[st.step][0])}</p><button data-track-mission="${m.id}">${S.tracked===m.id?'Untrack':'Track objective'}</button>`:st.status==='available'?`<p>Start by meeting ${npcs.find(n=>n.id===m.npc)?.name}.</p><button data-npc-waypoint="${m.npc}">Find starting character</button>`:'<p>✓ Completed · reward already received</p>'}</div>`}).join('')||'<div class="rl-card">Nothing here yet. Talk to a neighbour or complete your current mission to find the next story.</div>'}`}
function settingsHTML(){return `<p class="rl-muted">Settings save in this browser.</p>${[['master','Master volume'],['music','Music volume'],['effects','Effects volume'],['sensitivity','Camera sensitivity']].map(([id,n])=>`<label class="settingRow">${n}<input type="range" data-setting="${id}" min="${id==='sensitivity'?.4:0}" max="${id==='sensitivity'?2:1}" step=".05" value="${S.settings[id]}"></label>`).join('')}<label class="settingRow">Graphics quality<select data-setting="quality">${['low','auto','high'].map(x=>`<option ${x===S.settings.quality?'selected':''}>${x}</option>`).join('')}</select></label>${[['relaxed','Relaxed Hunger · no depletion'],['reduced','Reduced motion'],['bigTouch','Larger touch controls']].map(([id,n])=>`<label class="settingRow"><span><input type="checkbox" data-setting="${id}" ${S.settings[id]?'checked':''}> ${n}</span></label>`).join('')}<p><button data-ui="resetCamera">Reset camera</button> <button data-ui="help">Controls</button></p><h4>Save management</h4><button data-ui="manualSave">Save now</button> <button data-ui="resetGame">New game</button><p class="rl-muted">Autosaves use a versioned local save and a previous-save backup. Saves belong to this browser. Reset keeps your Rat Pack unlock.</p>`}
function shopHTML(){return `<p class="rl-muted">${near(npcs[1],5)?'Mabel: “Fair prices, honest paws.”':'Browse anywhere. Visit Mabel at the Rat Market to buy.'}</p><b>Balance: ${coins} coins</b><div class="rl-card"><b>Travel snack · 3 coins</b><p>Carry it and restore 35 hunger later.</p><button data-purchase="snack">Buy snack · 3</button></div>${Object.entries(decorDefs).filter(([k,d])=>d.cost&&(!d.pack||S.pack)).map(([k,d])=>`<div class="rl-card"><b>${d.icon} ${d.name}${d.pack?' · Rat Pack style':''}</b><p>Place in your nest. ${d.cost} coins.</p><button data-purchase="decor:${k}" ${S.decorOwned.includes(k)?'disabled':''}>${S.decorOwned.includes(k)?'Owned':'Buy · '+d.cost}</button></div>`).join('')}${Object.entries(styles).filter(([k,d])=>d.cost&&(!d.pack||S.pack)).map(([k,d])=>`<div class="rl-card"><b>${d.name}</b><p>Cosmetic style · ${d.cost} coins. No stat penalty.</p><button data-purchase="style:${k}" ${S.cosmetics.includes(k)?'disabled':''}>${S.cosmetics.includes(k)?'Owned':'Buy · '+d.cost}</button></div>`).join('')}<p class="rl-muted">The original market also sells speed, health and stomach upgrades, hats and weapons. Walk up to the stall and interact.</p>`}
function purchase(key){if(!near(npcs[1],5)){say('Visit Mabel at the Rat Market to buy.');return false}let cost=3,owned=false;if(key.startsWith('decor:')){const k=key.split(':')[1],d=decorDefs[k];if(!d||d.pack&&!S.pack)return false;cost=d.cost;owned=S.decorOwned.includes(k)}else if(key.startsWith('style:')){const k=key.split(':')[1],d=styles[k];if(!d||d.pack&&!S.pack)return false;cost=d.cost;owned=S.cosmetics.includes(k)}else if(key!=='snack')return false;if(owned||!cost||coins<cost){say(owned?'Already owned.':'Not enough coins.');return false}coins-=cost;if(key==='snack')S.bag.snack++;else if(key.startsWith('decor:'))S.decorOwned.push(key.split(':')[1]);else S.cosmetics.push(key.split(':')[1]);refreshHUD();save();say('Purchased · '+cost+' coins');return true}
function stylesHTML(){return `<p>Free styles are earned or bought with rat coins. Preview and equip in one tap.</p><div class="rl-card"><b>Current: ${styles[S.style]?.name||'Natural fur'}</b><p>Accessory: ${styles[S.accessory]?.name||'None'}</p><button data-equip="none">Remove accessory</button></div>${Object.entries(styles).filter(([k,d])=>!d.pack||S.pack).map(([k,d])=>`<div class="rl-card"><b>${d.name}</b><div style="height:30px;background:rgb(${(d.c||[.6,.4,.3]).map(x=>Math.min(255,Math.floor(x*110))).join(',')});border-radius:12px;margin:8px 0"></div><button data-equip="${k}" ${!S.cosmetics.includes(k)?'disabled':''}>${S.style===k||S.accessory===k?'Equipped':S.cosmetics.includes(k)?'Preview & equip':'Earn through play / market'}</button></div>`).join('')}`}
function nestHTML(){const inNest=near(nest,5);return `<p>${inNest?'Edit your nest. Click the floor to position a preview; green exit tiles remain clear.':'Preview your nest here. Return home to place or move furniture.'}</p><div class="previewNest" id="nestFloor"><div class="nestExit">EXIT</div>${S.decor.map((d,i)=>`<button data-nest-select="${i}" class="${nestSelected===i?'selected':''}" style="left:${(d.x+2)/4*100}%;top:${(d.z+2)/4*100}%;rotate:${d.r}deg">${decorDefs[d.id]?.icon||'▣'}</button>`).join('')}${nestPreview?`<span style="position:absolute;left:${(nestPreview.x+2)/4*100}%;top:${(nestPreview.z+2)/4*100}%;color:#e59d25;font-size:30px;transform:translate(-50%,-50%)">${decorDefs[nestPreview.id].icon}</span>`:''}</div><p class="rl-muted">Floor bounds ±1.5m. Front centre is the exit. Maximum 12 decorations.</p><label>Owned furniture<select id="nestChoice" class="rl-input">${S.decorOwned.filter(k=>decorDefs[k]&&(!decorDefs[k].pack||S.pack)).map(k=>`<option value="${k}">${decorDefs[k].name}</option>`).join('')}</select></label><p><button data-ui="previewDecor" ${!inNest?'disabled':''}>Preview item</button> <button data-ui="placeDecor" ${!inNest||!nestPreview?'disabled':''}>Place preview</button></p><p><button data-ui="rotateDecor" ${!inNest||nestSelected<0?'disabled':''}>Rotate selected</button> <button data-ui="removeDecor" ${!inNest||nestSelected<0?'disabled':''}>Remove selected</button></p><p><button data-ui="nestWaypoint">Find nest</button> <button data-ui="restNest" ${!inNest?'disabled':''}>Rest · restore hunger</button></p>`}
function musicHTML(){return `<div class="rl-card"><h4>♫ ${['Sewer Echoes','Backyard Beat','Cheese Dreams'][musicIndex]}</h4><p>${musicPlaying?'Playing':'Paused'} · Original procedural music</p><div class="rl-row"><button data-ui="musicPrev">‹ Previous</button><button data-ui="musicToggle">${musicPlaying?'Pause':'Play'}</button><button data-ui="musicNext">Next ›</button></div></div><label class="settingRow">Music volume<input type="range" data-setting="music" min="0" max="1" step=".05" value="${S.settings.music}"></label><p>Loops gently and continues when you close the phone. Respects master mute.</p>`}
function waypoint(loc){S.waypoint={name:loc.name,x:loc.x,z:loc.z,sewer:!!loc.sewer};say('Waypoint: '+loc.name);save()}
function near(o,r=2.4){return !!o&&!!o.sewer===underground&&Math.hypot(o.x-player.x,o.z-player.z)<r&&Math.abs(jumpY-(o.alt||0))<1.2}
function nestAllowed(d){return Math.abs(d.x)<=1.5&&Math.abs(d.z)<=1.5&&!(Math.abs(d.x)<.7&&d.z>.8)}
function placeDecor(){if(!near(nest,5)||!nestPreview||S.decor.length>=12||!nestAllowed(nestPreview)){say('Keep the exit clear and use the marked floor.');return false}if(S.decor.some(d=>Math.hypot(d.x-nestPreview.x,d.z-nestPreview.z)<.55)){say('That space is occupied. Choose another tile.');return false}S.decor.push({...nestPreview});nestSelected=S.decor.length-1;nestPreview=null;event('decorate');checkMissions();save();return true}
function calculate(expr){if(!/^[\d.()+\-*/\s]+$/.test(expr))return 'Error';try{const tokens=expr.match(/\d*\.?\d+|[()+\-*/]/g)||[];let index=0;function atom(){let t=tokens[index++];if(t==='-')return -atom();if(t==='+')return atom();if(t==='('){let n=add();if(tokens[index++]!==')')throw Error();return n}let n=Number(t);if(t===undefined||!Number.isFinite(n))throw Error();return n}function mul(){let n=atom();while(tokens[index]==='*'||tokens[index]==='/'){let op=tokens[index++],v=atom();n=op==='*'?n*v:n/v}return n}function add(){let n=mul();while(tokens[index]==='+'||tokens[index]==='-'){let op=tokens[index++],v=mul();n=op==='+'?n+v:n-v}return n}let n=add();if(index!==tokens.length||!Number.isFinite(n))return 'Error';return String(Number(n.toPrecision(12)))}catch{return 'Error'}}
function bindApp(){const el=$('phoneContent');el.querySelectorAll('[data-ui]').forEach(b=>b.onclick=()=>uiAction(b.dataset.ui));el.querySelectorAll('[data-dest]').forEach(b=>b.onclick=()=>{waypoint(landmarks.find(x=>x.id===b.dataset.dest));renderApp()});el.querySelectorAll('[data-npc-waypoint]').forEach(b=>b.onclick=()=>{waypoint(npcs.find(x=>x.id===b.dataset.npcWaypoint));renderApp()});el.querySelectorAll('[data-mission-tab]').forEach(b=>b.onclick=()=>{S.missionTab=b.dataset.missionTab;renderApp()});el.querySelectorAll('[data-track-mission]').forEach(b=>b.onclick=()=>{S.tracked=S.tracked===b.dataset.trackMission?'':b.dataset.trackMission;save();renderApp()});el.querySelectorAll('[data-purchase]').forEach(b=>b.onclick=()=>{purchase(b.dataset.purchase);renderApp()});el.querySelectorAll('[data-equip]').forEach(b=>b.onclick=()=>{let k=b.dataset.equip;if(k==='none')S.accessory='none';else if(S.cosmetics.includes(k)){if(styles[k].accessory)S.accessory=k;else S.style=k}save();renderApp()});el.querySelectorAll('[data-setting]').forEach(b=>b.oninput=()=>{const k=b.dataset.setting;S.settings[k]=b.type==='checkbox'?b.checked:b.type==='range'?Number(b.value):b.value;applyOptions();save(true)});el.querySelectorAll('[data-calc]').forEach(b=>b.onclick=()=>{const k=b.dataset.calc;if(k==='C')calc='0';else if(k==='⌫')calc=calc.length>1?calc.slice(0,-1):'0';else if(k==='=')calc=calculate(calc);else{const char=({'÷':'/','×':'*','−':'-'})[k]||k;calc=(calc==='0'||calc==='Error')?char:calc+char;if(calc.length>80)calc=calc.slice(0,80)}$('calcDisplay').textContent=calc});el.querySelectorAll('[data-route]').forEach(b=>b.onclick=()=>{const r=routes[b.dataset.route];waypoint({name:r.name+' start',x:r.points[0][0],z:r.points[0][1],sewer:r.sewer});renderApp()});el.querySelectorAll('[data-start-route]').forEach(b=>b.onclick=()=>startRoute(b.dataset.startRoute));el.querySelectorAll('[data-theme]').forEach(b=>b.onclick=()=>{S.theme=b.dataset.theme;applyTheme();save();renderApp()});el.querySelectorAll('[data-save-note]').forEach(b=>b.onclick=()=>{const i=+b.dataset.saveNote;S.notes[i].text=el.querySelector('[data-note="'+i+'"]').value;save();say('Note saved')});el.querySelectorAll('[data-delete-note]').forEach(b=>b.onclick=()=>{const i=+b.dataset.deleteNote;confirmAction('Delete this note?','This note will be removed. Other notes are kept.',()=>{S.notes.splice(i,1);save();renderApp()})});el.querySelectorAll('[data-nest-select]').forEach(b=>b.onclick=e=>{e.stopPropagation();nestSelected=+b.dataset.nestSelect;renderApp()});const floor=$('nestFloor');if(floor)floor.onclick=e=>{if(!near(nest,5))return;const rect=floor.getBoundingClientRect(),x=Math.round(((e.clientX-rect.left)/rect.width*4-2)*2)/2,z=Math.round(((e.clientY-rect.top)/rect.height*4-2)*2)/2;if(nestPreview){nestPreview.x=x;nestPreview.z=z}else if(S.decor[nestSelected]){const d={...S.decor[nestSelected],x,z};if(nestAllowed(d)&&!S.decor.some((o,i)=>i!==nestSelected&&Math.hypot(o.x-x,o.z-z)<.55)){S.decor[nestSelected]=d;save()}else say('Keep the exit clear and avoid occupied tiles.')}renderApp()};if($('photoFilter'))$('photoFilter').onchange=e=>{S.photoFilter=e.target.value;save()};}
function uiAction(id){switch(id){case 'home':home();break;case 'help':case 'styles':openApp(id);break;case 'manualSave':save();break;case 'resetGame':newGame();break;case 'resetCamera':resetCamera();break;case 'clearWaypoint':S.waypoint=null;save();renderApp();break;case 'eatSnack':if(S.bag.snack>0){S.bag.snack--;hunger=Math.min(100,hunger+35);save();refreshHUD();renderApp()}break;case 'storeSnack':case 'takeSnack':if(!near(nest,5)){say('Use your storage crate at home.');break}if(id==='storeSnack'&&S.bag.snack>0){S.bag.snack--;S.bag.stored=(S.bag.stored||0)+1}else if(id==='takeSnack'&&S.bag.stored>0){S.bag.stored--;S.bag.snack++}save();renderApp();break;case 'addNote':{const txt=$('noteDraft').value.trim();if(txt){S.notes.push({id:Date.now().toString(),text:txt.slice(0,4000)});save();renderApp()}break}case 'nestWaypoint':waypoint(nest);break;case 'previewDecor':nestPreview={id:$('nestChoice').value,x:1,z:-1,r:0};renderApp();break;case 'placeDecor':placeDecor();renderApp();break;case 'rotateDecor':if(near(nest,5)&&S.decor[nestSelected]){S.decor[nestSelected].r=(S.decor[nestSelected].r+90)%360;save();renderApp()}break;case 'removeDecor':if(near(nest,5)&&S.decor[nestSelected]){S.decor.splice(nestSelected,1);nestSelected=-1;save();renderApp()}break;case 'restNest':if(near(nest,5)){hunger=100;health=maxHealth();save();say('Rested at home.');renderApp()}break;case 'unstuck':closeRatPhone();safeReturn();break;case 'memoryWaypoint':waypoint(npcs[1]);break;case 'memory':closeRatPhone();startMemory();break;case 'musicToggle':initAudio();if(!audioContext){say('Audio is unavailable in this browser.');break}musicPlaying=!musicPlaying;audioContext.resume().catch(()=>say('Audio could not start. Tap Play again.'));renderApp();break;case 'musicPrev':musicIndex=(musicIndex+2)%3;musicStep=0;renderApp();break;case 'musicNext':musicIndex=(musicIndex+1)%3;musicStep=0;renderApp();break;case 'launchDrone':launchDrone();break;case 'photoMode':photoMode=true;closeRatPhone();document.body.classList.add('hudOff');break;case 'capture':capturePhoto();break;case 'downloadPhoto':if(photoData){const a=document.createElement('a');a.href=photoData;a.download='Ratlife-photo.png';a.click()}break}}
function applyOptions(){settings.sensitivity=clamp(finite(S.settings.sensitivity,1),.4,2);settings.quality=S.settings.quality;settings.sound=S.settings.master>0;globalThis.ratPixelCap=settings.quality==='low'?1:settings.quality==='high'?2:1.5;document.body.classList.toggle('reducedMotion',!!S.settings.reduced);document.body.classList.toggle('bigTouch',!!S.settings.bigTouch);if(windGain)windGain.gain.value=settings.sound&&!isUI()?.02*S.settings.master*S.settings.effects:0;if(musicGain)musicGain.gain.value=S.settings.master*S.settings.music*.05;resize();saveSettings()}
function applyTheme(){const colors={moss:['#779469','#193e36'],midnight:['#5a78a1','#1b2949'],sunset:['#cc9279','#653c45'],cheese:['#bbac61','#64582d']};const c=colors[S.theme]||colors.moss;document.querySelector('.phoneShell').style.background=`linear-gradient(145deg,${c[0]},${c[1]})`}
function safeReturn(){if(globalThis.MP?.active){globalThis.MP.command('recover').catch(e=>say(e.message));return}returnDrone();underground=false;player.x=nest.x;player.z=nest.z+3;insideBin=null;jumpY=jumpV=jetpackHeight=0;landJet();velocityX=velocityZ=0;cameraYaw=cameraPitch=null;hunger=Math.max(40,hunger);health=Math.max(30,health);alive=true;deathScreen.hidden=true;clear();save();say('Safely back at your nest. Progress kept.')}
function nearRoute(id){const r=routes[id];return r&&r.sewer===underground&&Math.hypot(player.x-r.points[0][0],player.z-r.points[0][1])<4}
function startRoute(id){const r=routes[id];if(!r||r.pack&&!S.pack||!nearRoute(id)){say('Go to the marked start first.');return false}activity={id,index:0,time:0};closeRatPhone();if(!r.pack)landJet();announce(r.name+' · Go!');return true}
function tickRoute(dt){if(!activity)return;const r=routes[activity.id];activity.time+=dt;if(activity.time>r.limit||underground!==r.sewer){say(r.name+' ended. Try again at the start.');activity=null;return}const p=r.points[activity.index];if(Math.hypot(player.x-p[0],player.z-p[1])<1.3&&(!r.pack||Math.abs(jumpY-p[2])<1.2)){activity.index++;sound(550+activity.index*80,.09,'triangle',.04);if(activity.index===r.points.length){const time=activity.time,id=activity.id;S.records[id]=Math.min(S.records[id]||Infinity,time);coins+=r.reward;activity=null;event('race:'+id);announce(r.name+' finished in '+time.toFixed(1)+'s · +'+r.reward+' coins');checks();save()}}}
let memoryRound=null,memoryTimers=[];
function startMemory(){if(!near(npcs[1],5)){say('Find Mabel at the market.');return}const seq=Array.from({length:4},()=>Math.floor(Math.random()*4));memoryRound={seq,idx:0,ready:false};showModal('Mabel’s Memory','<p id="memoryInfo">Watch and listen. Repeat the four-note pattern.</p><div style="display:grid;grid-template-columns:1fr 1fr;gap:10px">'+['Leaf','Cheese','Sky','Berry'].map((n,i)=>`<button class="rl-btn" id="memory${i}" style="background:${['#53784b','#a78a39','#5278a1','#a25763'][i]};min-height:70px" disabled>${n}</button>`).join('')+'</div>');memoryTimers.forEach(clearTimeout);seq.forEach((n,i)=>{memoryTimers.push(setTimeout(()=>{if(!memoryRound||$('rlModal').hidden)return;$('memory'+n).style.filter='brightness(1.8)';uiTone(330+n*120);memoryTimers.push(setTimeout(()=>{if($('memory'+n))$('memory'+n).style.filter=''},260))},500+i*600))});memoryTimers.push(setTimeout(()=>{if(!memoryRound||!$('memoryInfo'))return;memoryRound.ready=true;$('memoryInfo').textContent='Your turn.';for(let i=0;i<4;i++){$('memory'+i).disabled=false;$('memory'+i).onclick=()=>memoryTap(i)}},3100))}
function memoryTap(n){if(!memoryRound?.ready)return;uiTone(330+n*120);if(memoryRound.seq[memoryRound.idx]!==n){memoryRound=null;showModal('Good try!','<p>Mabel: “Even I mix up the shiny ones.”</p><button class="rl-btn" id="memoryAgain">Try again</button>');$('memoryAgain').onclick=startMemory;return}memoryRound.idx++;if(memoryRound.idx===4){memoryRound=null;coins+=6;event('memory');save();showModal('Perfect paws!','<p>Mabel: “You’ve got a keeper’s memory!”</p><p>+6 rat coins</p>')}}
function uiTone(freq){initAudio();if(!audioContext||!S.settings.master)return;const o=audioContext.createOscillator(),g=audioContext.createGain(),t=audioContext.currentTime;o.frequency.value=freq;g.gain.setValueAtTime(.05*S.settings.master*S.settings.effects,t);g.gain.exponentialRampToValueAtTime(.001,t+.25);o.connect(g);g.connect(audioContext.destination);o.start(t);o.stop(t+.25)}
function talk(n){const started=missions.find(m=>m.npc===n.id&&available(m)&&missionState(m).status==='available');const active=missions.filter(m=>missionState(m).status==='active');let text=({pip:'“A good day starts with a crumb and a friend.”',mabel:'“Everything has a use. Especially cheese.”',rivet:'“The pipes always lead somewhere. Watch for amber lamps.”',dash:'“Fast is fun. Finishing is better.”',fern:'“A warm nest makes a brave rat.”'})[n.id];for(const m of active){const st=missionState(m),kind=m.stages[st.step]?.[1];if(kind==='talk:'+n.id){completeStage(m);if(m.id==='delivery'&&st.step===1)S.bag.parcel=1;else if(m.id==='delivery'&&st.status==='done')delete S.bag.parcel;text=missionDialogue(m);break}if(kind==='favour:'+n.id){if(S.bag.snack>0){S.bag.snack--;completeStage(m);text='“A snack for me? You’re the best!”'}else text='“Could you bring me a travel snack? Mabel sells them.”';break}if(kind==='invites'&&['pip','fern'].includes(n.id)){st.flags=st.flags||[];if(!st.flags.includes(n.id))st.flags.push(n.id);text='“A picnic? Count me in!”';checkMissions();break}}
message(n.id,n.name+': '+text);showModal(n.name+' · '+n.role,`<p>🐀 ${esc(text)}</p>${started?`<div class="rl-card"><b>${esc(started.name)}</b><p>${esc(started.summary)}</p><small>${started.reward} coins + snack</small><p><button class="rl-btn" id="acceptMission">Start mission</button></p></div>`:''}<button class="rl-btn secondary" id="talkDone">Back to the backyard</button>${n.id==='mabel'?'<p><button class="rl-btn" id="talkShop">Browse new catalogue</button> <button class="rl-btn secondary" id="talkMemory">Memory challenge</button></p>':''}${n.id==='dash'?'<p><button class="rl-btn" id="talkRace">Activities</button></p>':''}`);if(started)$('acceptMission').onclick=()=>{startMission(started.id);closeModal();event('talk:'+n.id)};$('talkDone').onclick=closeModal;if($('talkShop'))$('talkShop').onclick=()=>{closeModal();openRatPhone('shop')};if($('talkMemory'))$('talkMemory').onclick=()=>{closeModal();startMemory()};if($('talkRace'))$('talkRace').onclick=()=>{closeModal();openRatPhone('activities')};save()}
function toggleFlight(){if(drone){returnDrone();return}if(!S.pack||isUI()||!alive)return;if(underground||biome(player.x,player.z)==='HOUSE'||insideBin){say('The jetpack needs open sky.');return}if(!jetpackActive&&S.flightFuel<12){say('Recharge on safe ground first.');return}jetpackActive=!jetpackActive;if(jetpackActive){uiTone(180);jumpV=0;say('Jetpack · Space / Jump rises · Ctrl / Down descends')}else{jumpV=0;say('Jetpack off · landing')}$('jetFlame').hidden=!jetpackActive}
function flightTick(dt){if(!S.pack){landJet();return}if(jetpackActive&&(isUI()||underground||biome(player.x,player.z)==='HOUSE'||insideBin||activity&&!routes[activity.id].pack)){landJet();return}if(jetpackActive){S.jetRecharge=globalThis.RATLIFE_CONFIG?.JETPACK_RECHARGE_DELAY??3;S.flightFuel=Math.max(0,S.flightFuel-dt*7);const up=ascend||keys.has(' '),down=descend||keys.has('control');jumpV=up?2.4:down?-2.4:0;jumpY=clamp(jumpY+jumpV*dt,.06,6);jetpackHeight=jumpY;if(S.flightFuel===0){landJet();say('Fuel empty — land to recharge.')}if(jumpY<=.07&&down)landJet()}else if(jumpY===0&&!isUI()){S.jetRecharge=Math.max(0,(S.jetRecharge||0)-dt);if(S.jetRecharge===0)S.flightFuel=Math.min(100,S.flightFuel+dt*24)}}
function launchDrone(){if(!S.pack||underground||insideBin||jumpY>.1||biome(player.x,player.z)==='HOUSE'){say('Launch outdoors on safe ground.');return}drone={x:player.x,z:player.z,y:3,time:25,originX:player.x,originZ:player.z};closeRatPhone();landJet();clear();say('Scout launched · Space rises · Ctrl descends · J returns')}
function returnDrone(){if(!drone)return;drone=null;clear();cameraYaw=cameraPitch=null;cameraArm=3.8;say('Scout returned safely.')}
function droneTick(dt){if(!drone)return;drone.time-=dt;if(isUI()||drone.time<=0){returnDrone();return}let ix=joy.x+(keys.has('d')||keys.has('arrowright')?1:0)-(keys.has('a')||keys.has('arrowleft')?1:0),iz=-joy.y+(keys.has('w')||keys.has('arrowup')?1:0)-(keys.has('s')||keys.has('arrowdown')?1:0),n=Math.max(1,Math.hypot(ix,iz));let x=drone.x+(ix*Math.cos(yaw)+iz*Math.sin(yaw))/n*6*dt,z=drone.z+(-ix*Math.sin(yaw)+iz*Math.cos(yaw))/n*6*dt;if(Math.hypot(x-drone.originX,z-drone.originZ)<25){drone.x=clamp(x,-66,66);drone.z=clamp(z,-66,66)}drone.y=clamp(drone.y+((ascend||keys.has(' ')?1:0)-(descend||keys.has('control')?1:0))*3*dt,4.5,8)}
function resetCamera(){yaw=player.angle;pitch=.36;cameraYaw=yaw;cameraPitch=pitch;cameraArm=3.8;say('Camera reset')}
function musicTick(){if(!S.pack||!musicPlaying||!audioContext)return;const t=audioContext.currentTime;if(t<musicNext)return;musicNext=t+.32;const songs=[[220,277.18,329.63,440,329.63,277.18,246.94,196],[196,246.94,293.66,392,293.66,246.94,220,293.66],[261.63,329.63,392,523.25,392,329.63,349.23,293.66]],seq=songs[musicIndex],o=audioContext.createOscillator(),g=audioContext.createGain();o.type=musicIndex===0?'sine':'triangle';o.frequency.value=seq[musicStep++%seq.length];g.gain.setValueAtTime(Math.max(.0001,.035*S.settings.master*S.settings.music),t);g.gain.exponentialRampToValueAtTime(.0001,t+.28);o.connect(g);g.connect(audioContext.destination);o.start(t);o.stop(t+.3)}
function capturePhoto(){if(!ratReady||!gl){if($('captureStatus'))$('captureStatus').textContent='3D rendering is unavailable in this browser; no photo was captured.';return}photoRender=true;photoTemp={phone:phoneOpen,menu:menuOpen};phoneOpen=false;phoneModeFrame();}
function phoneModeFrame(){requestAnimationFrame(()=>{try{drawRat(0);const c=document.createElement('canvas');c.width=ratCanvas.width;c.height=ratCanvas.height;const cx=c.getContext('2d');if(S.pack)cx.filter=({warm:'sepia(.35) saturate(1.2)',noir:'grayscale(1)',forest:'hue-rotate(20deg) saturate(.8)'})[S.photoFilter]||'none';cx.drawImage(ratCanvas,0,0);cx.filter='none';if(S.pack&&S.photoFilter==='postcard'){cx.strokeStyle='#efe5c7';cx.lineWidth=c.width*.045;cx.strokeRect(0,0,c.width,c.height);cx.fillStyle='#efe5c7';cx.font=Math.round(c.width*.035)+'px Georgia';cx.fillText('A little life. A big backyard.',c.width*.06,c.height*.93)}photoData=c.toDataURL('image/png');if(photoTemp?.phone)phoneOpen=true;if(currentApp==='camera')renderApp();sound(900,.08,'triangle',.03,500)}catch{if($('captureStatus'))$('captureStatus').textContent='This browser could not export the canvas. Use your device screenshot controls.'}finally{photoRender=false;photoTemp=null}})}
function objectiveText(){if(activity){const r=routes[activity.id];return {title:r.name,text:`${activity.index}/${r.points.length} checkpoints · ${(r.limit-activity.time).toFixed(1)}s left`}}if(drone)return {title:'Scout Drone',text:Math.ceil(drone.time)+'s · J / Escape returns safely'};const m=missions.find(m=>m.id===S.tracked);if(m){const st=missionState(m);if(st.status==='active')return {title:m.name,text:m.stages[st.step]?.[0]||'Complete'};if(st.status==='available')return {title:m.name,text:'Meet '+npcs.find(n=>n.id===m.npc)?.name+' to begin'}}return {title:'Explore the backyard',text:'Find hidden cheese, neighbours and new paths.'}}
function labels(){if(!cam||!ratReady)return;let out='';for(const n of npcs){if(!!n.sewer!==underground||Math.hypot(n.x-player.x,n.z-player.z)>13)continue;const p=project(n.x,ground(n.x,n.z)+1.1,n.z);if(p.d>.5&&p.x>0&&p.x<w&&p.y>0&&p.y<h)out+=`<span class="worldLabel" style="left:${p.x}px;top:${p.y}px">${n.name}${missions.some(m=>m.npc===n.id&&available(m)&&missionState(m).status==='available')?' · !':''}</span>`}$('gameLabels').innerHTML=out}
function tick(dt,t){if(modelUnavailable)return;musicTick();flightTick(dt);droneTick(dt);if(menuOpen&&!S.settings.reduced){const q=t*.00013;yaw=Math.sin(q)*.5;pitch=.34;player.angle=Math.sin(t*.0005)*.14;phase=Math.sin(t*.001)*.15}if(dt>0&&!isUI()&&!drone){S.gameTime+=dt*.6;worldTimer+=dt;uiTimer+=dt;if(jumpY<.03)lastGrounded=performance.now();if(jumpBuffer>0){jumpBuffer-=dt;if(jumpY<.04||performance.now()-lastGrounded<100){jumpV=4.8;jumpBuffer=0}}tickRoute(dt);for(const loc of landmarks){if(!!loc.sewer===underground&&!S.discovered.includes(loc.id)&&Math.hypot(player.x-loc.x,player.z-loc.z)<5){S.discovered.push(loc.id);if(!npcs.some(n=>n.id===loc.id)){coins+=2;say('Discovered '+loc.name+' · +2 coins')}save()}}for(const o of lootItems){if(o.pack&&!S.pack||S.collected.includes(o.id)||!!o.sewer!==underground)continue;if(Math.hypot(o.x-player.x,o.z-player.z)<.65&&Math.abs(jumpY-(o.alt||0))<.7&&o.kind!=='clue')collect(o)}if(worldTimer>1){worldTimer=0;checkMissions();checks()}if(performance.now()-lastSave>20000)save(true)}routeTick+=dt;if(uiTimer>.15||isUI()){uiTimer=0;const obj=objectiveText();$('objectiveHUD').innerHTML='<b>'+esc(obj.title)+'</b>'+esc(obj.text);const fuel=$('fuelHUD');fuel.hidden=!S.pack&&!drone;if(drone)fuel.innerHTML='SCOUT · '+Math.ceil(drone.time)+'s<br>J / Escape · return';else if(S.pack)fuel.innerHTML=(jetpackActive?'🚀 THRUST':S.jetRecharge>0?'🚀 WAIT '+S.jetRecharge.toFixed(1)+'s':'🚀 RECHARGING')+' '+Math.floor(S.flightFuel)+'%<progress max="100" value="'+S.flightFuel+'"></progress>';const wp=S.waypoint;$('waypointHUD').hidden=!wp;if(wp){const bearing=Math.atan2(wp.x-player.x,wp.z-player.z)-yaw,arrow=Math.abs(bearing)<.5?'↑':Math.sin(bearing)>0?'→':'←';$('waypointHUD').textContent=arrow+' '+wp.name+' · '+Math.round(Math.hypot(wp.x-player.x,wp.z-player.z))+'m'+(wp.sewer!==underground?' · '+(wp.sewer?'below ground':'surface'):'')}labels()}}
