// Extend rather than replace the original interaction / simulation chains.
const originalAction=doAction,originalFind=findAction,originalSurvival=updateSurvival,originalDraw=drawExpansion,originalRestart=restart,originalAttack=attack,originalSave=saveProgress,originalSound=sound;
function contextual(){if(!alive||insideBin||drone)return null;if(S.collected.includes('clue1')&&!underground&&Math.hypot(player.x+27,player.z-26)<1.7)return {type:'secretPipe'};const n=npcs.find(n=>near(n));if(n)return {type:'talkRat',object:n};const o=lootItems.find(o=>!S.collected.includes(o.id)&&(!o.pack||S.pack)&&near(o,1.25));if(o)return {type:'collectStory',object:o};if(near(nest,2.1))return {type:'nestStory'};for(const [id,r]of Object.entries(routes))if((!r.pack||S.pack)&&nearRoute(id)&&!activity)return {type:'routeStory',id};return null}
findAction=function(){return contextual()||originalFind()};
doAction=function(){if(isUI()||drone||!ratReady)return;if(globalThis.RatlifeBridge?.extraInteraction?.())return;const a=contextual();if(a?.type==='secretPipe'){underground=true;player.x=-24;player.z=8;jumpY=jumpV=0;landJet();cameraYaw=cameraPitch=null;clear();save();say('A secret pipe leads to the western junction.')}else if(a?.type==='talkRat')talk(a.object);else if(a?.type==='collectStory')collect(a.object);else if(a?.type==='nestStory')openRatPhone('nest');else if(a?.type==='routeStory')startRoute(a.id);else{const action=originalFind();originalAction();if(action?.type==='eat'||action?.type==='loot')save();if(underground)landJet()}};
actionButton.onclick=()=>doAction();
attack=function(){if(globalThis.MP?.active){say('Online uses co-op activities and preset emotes. Player combat is disabled.');return}if(isUI()||drone)return;originalAttack()};attackBtn.onclick=()=>attack();
updateSurvival=function(dt,speed){if(isUI()||drone||dt===0)return;const h=hunger;originalSurvival(dt,speed);if(S.settings.relaxed)hunger=Math.max(h,hunger);else hunger=Math.min(100,hunger+Math.max(0,h-hunger)*.7);if(underground){jumpY=Math.min(jumpY,1.55);if(jumpY>=1.55)jumpV=Math.min(0,jumpV)}if(!alive){activity=null;landJet();save()}const c=contextual();if(c)actionButton.textContent=c.type==='talkRat'?'Talk · '+c.object.name:c.type==='collectStory'?'Collect / inspect':c.type==='nestStory'?'Edit nest':c.type==='secretPipe'?'Enter secret pipe':'Start course';hungerFill.style.width=hunger+'%';hungerText.textContent=Math.ceil(hunger)+'%'};
drawExpansion=function(cube,tri){originalDraw(cube,tri);draw(cube,tri)};
saveProgress=function(){originalSave();save()};
restart=function(){originalRestart();landJet();returnDrone();activity=null;hunger=100;health=maxHealth();applyCollectedWorld();player.x=nest.x;player.z=nest.z+3;S.started=true;save()};$('restart').onclick=()=>restart();
function applyCollectedWorld(){if(S.world){coinDrops.forEach((o,i)=>o.taken=!!S.world.coins?.[i]);traps.forEach((o,i)=>o.sprung=!!S.world.traps?.[i])}}
sound=function(f,d=.08,type='sine',volume=.05,end=f){originalSound(f,d,type,volume*S.settings.master*S.settings.effects,end)};
