addEventListener('keydown',e=>{if(globalThis.RatlifeCommunity?.key(e))return;if(globalThis.RatDeck?.opened)return;if(globalThis.MP?.ui){if(e.key==='Escape')globalThis.MP.closeUI();if(!/INPUT|TEXTAREA|SELECT/.test(e.target.tagName))e.stopImmediatePropagation();return}if(globalThis.RatlifeExtraUI){if(e.key==='Escape')globalThis.MP?.closeGarage();e.stopImmediatePropagation();return}const input=/INPUT|TEXTAREA|SELECT/.test(e.target.tagName),k=e.key.toLowerCase();if(input&&e.key!=='Escape'){e.stopImmediatePropagation();return}if(e.key==='Escape'){e.preventDefault();e.stopImmediatePropagation();if(!plusCode.hidden){plusCode.hidden=true;return}if(modalOpen){closeModal();return}if(photoMode){photoMode=false;document.body.classList.remove('hudOff');return}if(drone){returnDrone();return}if(phoneOpen){if(currentApp)home();else closeRatPhone();return}if(menuOpen)return;if(shopOpen){closeShop();return}togglePause();return}if(k==='m'&&!e.repeat&&!menuOpen&&!modalOpen){e.preventDefault();e.stopImmediatePropagation();phoneOpen?closeRatPhone():openRatPhone();return}if(isUI()){e.stopImmediatePropagation();return}if(e.code==='Space'){e.preventDefault();e.stopImmediatePropagation();keys.add(' ');if(!jetpackActive&&!drone&&!e.repeat)jumpBuffer=.14;return}if(k==='shift'){keys.add('shift');return}if(k==='control'){keys.add('control');e.preventDefault();return}if(k==='j'&&!e.repeat){e.stopImmediatePropagation();if(globalThis.MP?.active)globalThis.MP.jet();else toggleFlight();return}if(k==='r'&&!e.repeat){e.stopImmediatePropagation();resetCamera();return}if(k==='p'){e.stopImmediatePropagation();togglePause();return}},true);
addEventListener('keyup',e=>{if(e.code==='Space')keys.delete(' ');if(e.key==='Control')keys.delete('control');if(e.key==='Shift')keys.delete('shift')},true);
